def caesar_cipher_encrypt(text, shift):
    encrypted_text = ''
    alphabet_lower = []
    alphabet_upper = []

    for i in range(26):
        alphabet_lower.append(chr(ord('a') + i))
        alphabet_upper.append(chr(ord('A') + i))

    shifted_lower = []
    shifted_upper = []

    for char_code in range(26):
        shifted_lower.append(alphabet_lower[(char_code + shift) % 26])
        shifted_upper.append(alphabet_upper[(char_code + shift) % 26])

    mapping_lower = {}
    mapping_upper = {}

    for i in range(26):
        mapping_lower[alphabet_lower[i]] = shifted_lower[i]
        mapping_upper[alphabet_upper[i]] = shifted_upper[i]

    for char in text:
        if 'a' <= char <= 'z':
            encrypted_text += mapping_lower[char]
        elif 'A' <= char <= 'Z':
            encrypted_text += mapping_upper[char]
        else:
            encrypted_text += char

    return encrypted_text

